def abstain_labels(scores, threshold, margin):
    if margin < 0:
        raise ValueError("margin must be non-negative")
    labels = []
    for score in scores:
        if abs(score - threshold) <= margin:
            labels.append("abstain")
        elif score > threshold:
            labels.append("right")
        else:
            labels.append("left")
    return labels

