import math

def device_summary(samples, threshold):
    if not samples:
        raise ValueError("At least one sample is required")
    episodes, previous_above = 0, False
    for sample in samples:
        above = sample >= threshold
        if above and not previous_above:
            episodes += 1
        previous_above = above
    rms = math.sqrt(sum(s * s for s in samples) / len(samples))
    return [len(samples), episodes, rms]

print(device_summary([0, 3, 4, 0, 5], 2))

def count_episodes(samples, threshold):
    count, previous_above = 0, False
    for sample in samples:
        above = sample >= threshold
        if above and not previous_above:
            count += 1
        previous_above = above
    return count

def toy_pipeline(trials, baselines, threshold, weights, bias, step):
    if len(baselines) != 2 or len(weights) != 2 or step <= 0:
        raise ValueError("Two baselines, two weights and a positive step are required")
    features, labels, positions = [], [], [0]
    for trial in trials:
        if len(trial) != 2:
            raise ValueError("Each trial needs exactly two channels")
        counts = [count_episodes([s - baselines[c] for s in trial[c]], threshold) for c in range(2)]
        score = weights[0] * counts[0] + weights[1] * counts[1] + bias
        label = "right" if score > 0 else "left"
        features.append(counts)
        labels.append(label)
        positions.append(positions[-1] + step if label == "right" else positions[-1] - step)
    return {"features": features, "labels": labels, "positions": positions}

trials = [[[10, 17, 11, 16, 10], [20, 21, 20, 22, 20]],
          [[10, 11, 10, 10, 12], [20, 27, 26, 20, 28]],
          [[10, 16, 10, 10, 10], [20, 26, 20, 20, 20]]]
print(toy_pipeline(trials, [10, 20], 5, [-1, 1], 0, 1))
